export function LocalState({
  componentLabel = "{{componentLabel}}",
  countA = {{countA}},
  countB = {{countB}},
  accent = "{{accent}}",
}) {
  const box = { flex: 1, border: `2px solid ${accent}`, borderRadius: 10, padding: 12, textAlign: "center" };
  return (
    <div style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 12px", fontSize: 11, color: "#24143099" }}>Two independent &lt;{componentLabel}&gt; instances &mdash; each owns its own count.</p>
      <div style={{ display: "flex", gap: 10 }}>
        <div style={box}><small style={{ display: "block", fontSize: 10, color: "#24143099", marginBottom: 6 }}>{componentLabel} A</small><strong style={{ fontSize: 24 }}>{countA}</strong></div>
        <div style={box}><small style={{ display: "block", fontSize: 10, color: "#24143099", marginBottom: 6 }}>{componentLabel} B</small><strong style={{ fontSize: 24 }}>{countB}</strong></div>
      </div>
    </div>
  );
}
